class Solution:
    def rotateRight(self, head: Optional[ListNode], k: int) -> Optional[ListNode]:
        if not head or not head.next or k == 0:
            return head
        length = 1
        tail = head
        while tail.next:
            tail = tail.next
            length += 1
        k %= length
        if k == 0:
            return head
        tail.next = head
        steps = length - k
        for _ in range(steps):
            tail = tail.next
        new_head = tail.next
        tail.next = None
        return new_head

class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if (!head || !head->next || k == 0) return head;
        int length = 1;
        ListNode* tail = head;
        while (tail->next) {
            tail = tail->next;
            length++;
        }
        k %= length;
        if (k == 0) return head;
        tail->next = head;
        int steps = length - k;
        for (int i = 0; i < steps; i++) tail = tail->next;
        ListNode* newHead = tail->next;
        tail->next = nullptr;
        return newHead;
    }
};

class Solution {
    public ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0) return head;
        int length = 1;
        ListNode tail = head;
        while (tail.next != null) {
            tail = tail.next;
            length++;
        }
        k %= length;
        if (k == 0) return head;
        tail.next = head;
        int steps = length - k;
        for (int i = 0; i < steps; i++) tail = tail.next;
        ListNode newHead = tail.next;
        tail.next = null;
        return newHead;
    }
}

var rotateRight = function(head, k) {
    if (!head || !head.next || k === 0) return head;
    let length = 1;
    let tail = head;
    while (tail.next !== null) {
        tail = tail.next;
        length++;
    }
    k %= length;
    if (k === 0) return head;
    tail.next = head;
    const steps = length - k;
    for (let i = 0; i < steps; i++) tail = tail.next;
    const newHead = tail.next;
    tail.next = null;
    return newHead;
};
